private static double Cos(float[] a, float[] b)
    {
        double dot = 0, na = 0, nb = 0;
        for (int i = 0; i < a.Length; i++)
        {
            dot += a[i] * b[i];
            na += a[i] * a[i];
            nb += b[i] * b[i];
        }
        var denom = System.Math.Sqrt(na) * System.Math.Sqrt(nb);
        return denom > 0 ? dot / denom : 0;
    }

